insert into svas.tarifa_plan (plan_id, tasa_base, parametros)
select p.id, v.tasa_base, v.parametros::jsonb from (values
  ('RIMAC', 'Plata', 0.0300, '{}'),
  ('RIMAC', 'Oro', 0.0420, '{}'),
  ('PACIFICO', 'Básico', 0.0280, '{"cargo_fijo_anual": 30}'),
  ('PACIFICO', 'Premium', 0.0400, '{"cargo_fijo_anual": 45}'),
  ('LA_POSITIVA', 'Clásico', 0.0300, '{"recargo_pago_mensual": 0.05}'),
  ('LA_POSITIVA', 'Full', 0.0430, '{"recargo_pago_mensual": 0.05}'),
  ('MAPFRE', 'Esencial', 0.0290, '{"prima_minima_anual": 180}'),
  ('MAPFRE', 'Total', 0.0410, '{"prima_minima_anual": 250}'),
  ('QUALITAS', 'Estándar', 0.0310, '{"descuento_comercial": 0.05}'),
  ('QUALITAS', 'Plus', 0.0440, '{"descuento_comercial": 0.05}')
) as v (codigo, plan, tasa_base, parametros)
join svas.aseguradora a on a.codigo_estrategia = v.codigo
join svas.plan p on p.aseguradora_id = a.id and p.nombre = v.plan
on conflict (plan_id) do nothing;

