join svas.aseguradora a on a.codigo_estrategia = v.codigo
join svas.marca ma on ma.nombre = v.marca
join svas.modelo mo on mo.marca_id = ma.id and mo.nombre = v.modelo
on conflict (aseguradora_id, modelo_id) do nothing;

