-- Verificación: si un join no encontró su fila (nombre distinto), falta algo y se aborta.
do $$
begin
  if (select count(*) from svas.marca) < 21 then
    raise exception 'Seed 0017 incompleto: svas.marca tiene menos de 21 filas';
  end if;
  if (select count(*) from svas.tipo_vehiculo) < 5 then
    raise exception 'Seed 0017 incompleto: svas.tipo_vehiculo tiene menos de 5 filas';
  end if;
  if (select count(*) from svas.modelo) < 68 then
    raise exception 'Seed 0017 incompleto: svas.modelo tiene menos de 68 filas';
  end if;
  if (select count(*) from svas.ubigeo) < 73 then
    raise exception 'Seed 0017 incompleto: svas.ubigeo tiene menos de 73 filas';
  end if;
  if (select count(*) from svas.tarifa_plan) < 10 then
    raise exception 'Seed 0017 incompleto: svas.tarifa_plan tiene menos de 10 filas';
  end if;
  if (select count(*) from svas.rango_suma_asegurada) < 4080 then
    raise exception 'Seed 0017 incompleto: svas.rango_suma_asegurada tiene menos de 4080 filas';
  end if;
  if (select count(*) from svas.peso_marca) < 105 then
    raise exception 'Seed 0017 incompleto: svas.peso_marca tiene menos de 105 filas';
  end if;
  if (select count(*) from svas.peso_modelo) < 340 then
    raise exception 'Seed 0017 incompleto: svas.peso_modelo tiene menos de 340 filas';
  end if;
  if (select count(*) from svas.peso_anio) < 60 then
    raise exception 'Seed 0017 incompleto: svas.peso_anio tiene menos de 60 filas';
  end if;
  if (select count(*) from svas.peso_tipo) < 5 then
    raise exception 'Seed 0017 incompleto: svas.peso_tipo tiene menos de 5 filas';
  end if;
  if (select count(*) from svas.peso_ubigeo) < 73 then
    raise exception 'Seed 0017 incompleto: svas.peso_ubigeo tiene menos de 73 filas';
  end if;
end;
$$;
